mapper.select:
SELECT id, dict_code AS dictCode, dict_value AS dictValue, dict_label AS dictLabel, parent_value AS parentValue, sort, status, organization_id AS organizationId, create_time AS createTime FROM ad_dict WHERE organization_id = #{organizationId} AND deleted = 0
AND dict_code = #{dictCode}
AND (dict_label LIKE CONCAT('%', #{keyword}, '%') OR dict_value LIKE CONCAT('%', #{keyword}, '%') OR dict_code LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
ORDER BY sort ASC, create_time DESC
